from cwe_335_0 import generate_key
import unittest
from unittest.mock import patch

class TestGenerateKeyFunctionality(unittest.TestCase):

    @patch('os.urandom')
    @patch('random.getrandbits')
    def test_generate_key_16_128(self, mock_getrandbits, mock_urandom):
        # Mock the return values
        mock_urandom.return_value = b'\xff' * 16
        mock_getrandbits.return_value = 224899044034084921726554508870453362736

        # Call the function
        key = generate_key(16, 128)

        # Assert the expected result
        self.assertEqual(key, 224899044034084921726554508870453362736)

    @patch('os.urandom')
    @patch('random.getrandbits')
    def test_generate_key_8_64(self, mock_getrandbits, mock_urandom):
        # Mock the return values
        mock_urandom.return_value = b'\xff' * 8
        mock_getrandbits.return_value = 9327924624971283046

        # Call the function
        key = generate_key(8, 64)

        # Assert the expected result
        self.assertEqual(key, 9327924624971283046)

    @patch('os.urandom')
    @patch('random.getrandbits')
    def test_generate_key_32_256(self, mock_getrandbits, mock_urandom):
        # Mock the return values
        mock_urandom.return_value = b'\xff' * 32
        mock_getrandbits.return_value = 101033378944694936479610297980616834863566069622307528113565112716060276178896

        # Call the function
        key = generate_key(32, 256)

        # Assert the expected result
        self.assertEqual(key, 101033378944694936479610297980616834863566069622307528113565112716060276178896)

if __name__ == '__main__':
    unittest.main()

