from cwe_502_0 import confirm_auth, AuthFail
import base64
import pickle
import pytest
from unittest.mock import Mock


# Mock functions
def mock_check_hmac_function(signature, data, secret_key):
    return signature == 'valid_signature' and data == 'user_data' and secret_key == 'secret'

def mock_get_secret_key_function():
    return 'secret'

# Test Cases
def test_confirm_auth_success():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({'signature': 'valid_signature', 'data': 'user_data'}))
    }
    result = confirm_auth(headers, mock_check_hmac_function, mock_get_secret_key_function)
    assert result == 'user_data'

def test_confirm_auth_invalid_signature():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({'signature': 'invalid_signature', 'data': 'user_data'}))
    }
    with pytest.raises(AuthFail):
        confirm_auth(headers, mock_check_hmac_function, mock_get_secret_key_function)

def test_confirm_auth_no_auth_token():
    headers = {}
    with pytest.raises(KeyError):
        confirm_auth(headers, mock_check_hmac_function, mock_get_secret_key_function)

def test_confirm_auth_invalid_token_format():
    headers = {
        'AuthToken': b'invalid_base64'
    }
    with pytest.raises(Exception):
        confirm_auth(headers, mock_check_hmac_function, mock_get_secret_key_function)

def test_confirm_auth_with_mock_object():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({'signature': 'valid_signature', 'data': 'user_data'}))
    }
    check_hmac_mock = Mock(return_value=True)
    secret_key_mock = Mock(return_value='secret')

    result = confirm_auth(headers, check_hmac_mock, secret_key_mock)

    assert result == 'user_data'
    check_hmac_mock.assert_called_once_with('valid_signature', 'user_data', 'secret')
    secret_key_mock.assert_called_once()

from cwe_502_0 import confirm_auth
import pytest
import base64
import pickle


class AuthFail(Exception):
    pass


def mock_check_hmac_valid(signature, data, secret_key):
    return signature == 'valid_signature' and data == 'user_data' and secret_key == 'secret'


def mock_check_hmac_invalid(signature, data, secret_key):
    return False


def mock_get_secret_key():
    return 'secret'


def test_confirm_auth_valid():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({
            'signature': 'valid_signature',
            'data': 'user_data'
        })).decode('utf-8')
    }
    secure_data = confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)
    assert secure_data == 'user_data', "Valid token should return user data"


def test_confirm_auth_missing_token():
    headers = {}
    with pytest.raises(KeyError):
        confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)


def test_confirm_auth_invalid_hmac():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({
            'signature': 'invalid_signature',
            'data': 'user_data'
        })).decode('utf-8')
    }
    with pytest.raises(AuthFail):
        confirm_auth(headers, mock_check_hmac_invalid, mock_get_secret_key)


def test_confirm_auth_invalid_base64():
    headers = {
        'AuthToken': 'invalid_base64'
    }
    with pytest.raises(AuthFail):
        confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)


def test_confirm_auth_corrupted_pickle_data():
    headers = {
        'AuthToken': base64.b64encode(b'not_a_valid_pickle').decode('utf-8')
    }
    with pytest.raises(AuthFail):
        confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)


def test_confirm_auth_missing_data_fields():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({
            'signature': 'valid_signature'
        })).decode('utf-8')
    }
    with pytest.raises(AuthFail):
        confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)


def test_confirm_auth_malicious_payload():
    class Malicious:
        def __reduce__(self):
            return (eval, ("__import__('os').system('echo vulnerable')",))

    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({
            'signature': 'valid_signature',
            'data': Malicious()
        })).decode('utf-8')
    }
    with pytest.raises(AuthFail):
        confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)


def test_confirm_auth_replay_attack():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({
            'signature': 'valid_signature',
            'data': 'user_data'
        })).decode('utf-8')
    }
    confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)
    # Simulate replay attack
    secure_data = confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)
    assert secure_data == 'user_data', "Replay should not raise if not restricted"


def test_confirm_auth_unexpected_data_type():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({
            'signature': 'valid_signature',
            'data': 12345  # Integer instead of string
        })).decode('utf-8')
    }
    secure_data = confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)
    assert secure_data == 12345, "Function should handle unexpected data types"


def test_confirm_auth_null_byte_injection():
    headers = {
        'AuthToken': base64.b64encode(pickle.dumps({
            'signature': 'valid_signature',
            'data': 'user_data\x00'
        })).decode('utf-8')
    }
    secure_data = confirm_auth(headers, mock_check_hmac_valid, mock_get_secret_key)
    assert secure_data == 'user_data\x00', "Null byte injection should be handled correctly"

