from cwe_1389_1 import validate_ip_regex, run_ping_regex
import pytest
from unittest.mock import patch

# Test cases for validate_ip_regex
@pytest.mark.parametrize("ip, expected", [
    ("192.168.1.1", "192.168.1.1"),
    ("10.0.0.1", "10.0.0.1"),
    ("255.255.255.255", "255.255.255.255")
])
def test_validate_ip_regex_valid(ip, expected):
    assert validate_ip_regex(ip) == expected

@pytest.mark.parametrize("ip", [
    "256.300.1.1",
    "999.999.999.999",
    "abc.def.ghi.jkl",
    "192.168.1"
])
def test_validate_ip_regex_invalid(ip):
    with pytest.raises(ValueError):
        validate_ip_regex(ip)

# Test cases for run_ping_regex
@patch('subprocess.call', return_value=0)
def test_run_ping_regex_valid(mock_subprocess_call):
    ip = "192.168.1.1"
    result = run_ping_regex(ip)
    mock_subprocess_call.assert_called_with(['ping', '-c', '1', ip])
    assert result == 0

@patch('subprocess.call', return_value=1)
def test_run_ping_regex_unreachable(mock_subprocess_call):
    ip = "192.0.2.0"
    result = run_ping_regex(ip)
    mock_subprocess_call.assert_called_with(['ping', '-c', '1', ip])
    assert result == 1

