class StringComparisonTest {

    @Test
    void testAreSameObjectWithNewStrings() {
        // Create two new String objects with the same content
        String str1 = new String("Hello");
        String str2 = new String("Hello");

        // Verify that areSameObject returns false for different objects
        assertFalse(StringComparison.areSameObject(str1, str2));
    }

    @Test
    void testAreSameObjectWithStringLiterals() {
        // Use string literals, which refer to the same object in the string pool
        String str1 = "Hello";
        String str2 = "Hello";

        // Verify that areSameObject returns true for same objects
        assertTrue(StringComparison.areSameObject(str1, str2));
    }

    @Test
    void testAreSameObjectWithLiteralAndNewString() {
        // Create one literal and one new String object with the same content
        String str1 = "Hello";
        String str2 = new String("Hello");

        // Verify that areSameObject returns false for different objects
        assertFalse(StringComparison.areSameObject(str1, str2));
    }

    @Test
    void testPrintResultTrue() {
        // Mock the output stream to verify print statements
        PrintStream out = mock(PrintStream.class);
        System.setOut(out);

        // Print "str1 == str2" for true
        StringComparison.printResult(true);

        // Verify that "str1 == str2" was printed
        verify(out).println("str1 == str2");
    }

    @Test
    void testPrintResultFalse() {
        // Mock the output stream to verify no print statements for false
        PrintStream out = mock(PrintStream.class);
        System.setOut(out);

        // Do not print anything for false
        StringComparison.printResult(false);

        // Verify that nothing was printed
        verify(out, never()).println("str1 == str2");
    }
}

