    void testCrossSiteScripting() {
        // Testing XSS injection
        form.setName("<script>alert('XSS')</script>");
        form.setEmail("alice@example.com");

        // The script should not execute and should be sanitized
        assertNotEquals("<script>alert('XSS')</script>", form.getName());
