        // Testing buffer overflow
        String longString = generateLongString(10000);
        form.setName(longString);
        form.setEmail(longString);

        // Ensure the application handles long strings gracefully
        assertEquals(longString, form.getName());
        assertEquals(longString, form.getEmail());
    }

    @Test
    void testLDAPInjection() {
        // Testing LDAP injection
        form.setName("*)(cn=*))");
        form.setEmail("alice@example.com");

        // Validate the input is properly sanitized
