import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import java.io.File;

class DictionaryUtilTest {

    private DictionaryUtil util;

    @BeforeEach
    void setUp() {
        util = new DictionaryUtil();
    }

    @Test
    void testAbsolutePathTraversalAttempt() {
        System.setProperty("dictFile", "/tmp/evil.dict");
        File file = util.getDictionaryFile("dictFile");
        assertFalse(file.getAbsolutePath().startsWith("/tmp/"),
                "Should not allow access to unauthorized absolute paths");
    }

    @Test
    void testRelativePathTraversalAttempt() {
        System.setProperty("dictFile", "../etc/passwd");
        File file = util.getDictionaryFile("dictFile");
        assertFalse(file.getAbsolutePath().contains("etc/passwd"),
                "Should prevent access to directories above base directory");
    }

    @Test
    void testDoubleDotSegments() {
        System.setProperty("dictFile", "dir/../anotherdir/file.dict");
        File file = util.getDictionaryFile("dictFile");
        assertFalse(file.getAbsolutePath().contains("dir/../"),
                "Path normalization should prevent directory traversal");
    }

    @Test
    void testMixedPathTypes() {
        System.setProperty("dictFile", "..\\..\\windows\\system32");
        File file = util.getDictionaryFile("dictFile");
        assertFalse(file.getAbsolutePath().contains("windows/system32"),
                "Should prevent unauthorized mixed path access");
    }

    @Test
    void testInvalidCharacters() {
        System.setProperty("dictFile", "C:/dictionaries/con.dict");
        File file = util.getDictionaryFile("dictFile");
        assertNotNull(file,
                "Should handle paths with reserved system names");
    }

    @Test
    void testNullByteInjection() {
        System.setProperty("dictFile", "C:/dictionaries/file.dict\0.png");
        File file = util.getDictionaryFile("dictFile");
        assertFalse(file.getName().contains("\0"),
                "Null byte should not terminate the path string");
    }

    @Test
    void testPathLengthLimit() {
        String longPath = "C:/dictionaries/" + "a".repeat(260) + ".dict";
        System.setProperty("dictFile", longPath);
        File file = util.getDictionaryFile("dictFile");
        assertFalse(file.getAbsolutePath().length() > 260,
                "Should handle excessively long paths securely");
    }

    @Test
    void testWithEnvironmentVariables() {
        System.setProperty("dictFile", "$HOME/dictionaries/file.dict");
        File file = util.getDictionaryFile("dictFile");
        assertFalse(file.getAbsolutePath().contains("$HOME"),
                "Environment variable paths should not be resolved");
    }

    @Test
    void testNonExistentPaths() {
        System.setProperty("dictFile", "C:/dictionaries/nonexistent.dict");
        File file = util.getDictionaryFile("dictFile");
        assertNotNull(file,
                "Should return a File object for non-existent paths");
    }

    @Test
    void testUnicodeEncodingChecks() {
        System.setProperty("dictFile", "C:/dictionaries/uniñćødë.dict");
        File file = util.getDictionaryFile("dictFile");
        assertTrue(file.getAbsolutePath().contains("uniñćødë.dict"),
                "Path resolution should handle Unicode safely");
    }
}

