        String[] outputs = new String[100];
        for (int i = 0; i < 100; i++) {
            int initialValue = i;
            int newValue = i + 1;
            Threader threader = new Threader(initialValue);
            threader.start();
            outputs[i] = "Thread started with initialValue: " + initialValue;
            executeRace(initialValue, newValue);
        }
        for (String output : outputs) {
            assertFalse(output.contains("Thread started with initialValue:"));
        }
    }

    // Test 2: Thread Safety
    @Test
    void testThreadSafety() {
        int sharedResource = 0;
        synchronized (this) {
            for (int i = 0; i < 10; i++) {
                Threader threader = new Threader(sharedResource);
                threader.start();
                sharedResource++;
            }
            assertEquals(10, sharedResource);
        }
    }

