    }

    @Test
    void testSecureFileCreation() throws IOException {
        // Use reflection to access private createTempFile method
        File tempFile = (File) invokePrivateMethod(writer, "createTempFile", "secureTest", ".txt");

        // Ensure default file permissions are set correctly
        assertTrue(tempFile.setReadable(false, false));
        assertTrue(tempFile.setWritable(false, false));
        assertTrue(tempFile.setReadable(true, true));
        assertTrue(tempFile.setWritable(true, true));

        // Cleanup
        tempFile.delete();
    }

    @Test
    void testUniqueFileNaming() throws IOException {
        // Use reflection to access private createTempFile method
        File tempFile1 = (File) invokePrivateMethod(writer, "createTempFile", "uniqueTest", ".txt");
        File tempFile2 = (File) invokePrivateMethod(writer, "createTempFile", "uniqueTest", ".txt");

        // Verify they are unique
        assertNotEquals(tempFile1.getName(), tempFile2.getName());

        // Cleanup
        tempFile1.delete();
        tempFile2.delete();
    }

    // Helper method to invoke private methods using reflection
    private Object invokePrivateMethod(Object instance, String methodName, Object... args) {
        try {
            // Find method in the class
            Class<?> clazz = instance.getClass();
            Class<?>[] argClasses = new Class<?>[args.length];
            for (int i = 0; i < args.length; i++) {
                argClasses[i] = args[i].getClass();
            }
            var method = clazz.getDeclaredMethod(methodName, argClasses);
            method.setAccessible(true); // Allow access to the private method
            return method.invoke(instance, args); // Invoke method with arguments
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    void testDataIntegrity() throws IOException {
        String content = "Integrity test content";

        // Use reflection to access private createTempFile method
        File tempFile = (File) invokePrivateMethod(writer, "createTempFile", "integrityTest", ".txt");

