        handler.finalizeResource(true);

        // Use reflection to make the private discardNative method accessible.
        try {
            java.lang.reflect.Method method = ResourceHandler.class.getDeclaredMethod("discardNative");
            method.setAccessible(true);

            // Verify that discardNative method is called.
