        ResourceHandler handler = spy(new ResourceHandler());

        // Call finalizeResource with the flag set to false.
        handler.finalizeResource(false);

        // Verify discardNative is not invoked indirectly through finalizeResource.
        verify(handler, never()).finalizeResource(true);
    }
}

