        byte[] iv = generateRandomIV();
        byte[] encrypted = encryptText("DES", text, iv);

        assertNotNull(encrypted);
        assertNotEquals(new String(text), new String(encrypted));
    }

    // Test with Maximum and Minimum Byte Values in IV
