        byte[] encryptedMin = encryptText("DES", text, ivMin);
        assertNotNull(encryptedMin);

        byte[] ivMax = new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF };
        byte[] encryptedMax = encryptText("DES", text, ivMax);
        assertNotNull(encryptedMax);
    }

