class ErrorHandlingTest {

    private ErrorHandling errorHandling;

    @BeforeEach
    void setUp() {
        errorHandling = new ErrorHandling();
    }

    @Test
    void testExecuteTryCatch_NoExceptionThrown() {
        // Arrange
        ErrorHandling mockErrorHandling = spy(errorHandling);

        // Act & Assert
        assertDoesNotThrow(() -> mockErrorHandling.executeTryCatch());

        // Verify that coreLogic is called
        verify(mockErrorHandling, times(1)).coreLogic();
    }

    @Test
    void testExecuteTryCatch_ExceptionThrown() {
        // Arrange
        ErrorHandling mockErrorHandling = spy(errorHandling);
        doThrow(new ArithmeticException("Division by zero")).when(mockErrorHandling).coreLogic();

        // Redirect console output
        String consoleOutput = captureConsoleOutput(() -> {
            // Act
            mockErrorHandling.executeTryCatch();
        });

        // Assert the exception message is printed
        assertTrue(consoleOutput.contains("Division by zero"));

        // Verify that handleException is called
        verify(mockErrorHandling, times(1)).handleException(any(ArithmeticException.class));
    }

    @Test
    void testProcessValues() {
        // Capture console output
        String consoleOutput = captureConsoleOutput(() -> {
            errorHandling.processValues(5, 10);
        });

        // Assert that processValues prints correctly
        assertEquals("Processing: 5 and 10" + System.lineSeparator(), consoleOutput);
    }

    // Helper method to capture console output
    private String captureConsoleOutput(Runnable executable) {
        // Save the original System.out
        PrintStream originalOut = System.out;
        // Create a new ByteArrayOutputStream to capture output
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        // Set the new PrintStream to capture output
        System.setOut(new PrintStream(baos));

        // Run the provided executable
        executable.run();

        // Restore the original System.out
        System.setOut(originalOut);
        // Return the captured output as a String
        return baos.toString();
    }
}

