import static org.mockito.Mockito.*;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;

class FileHandlerTest {

    private FileHandler fileHandler;

    @BeforeEach
    void setUp() {
        fileHandler = new FileHandler();
    }

    @Test
    void testWriteFileWithTxtSuffix() throws IOException {
        // Given
        String prefix = "example1";
        String suffix = ".txt";
        String content = "This is a test file.";

        // When
        fileHandler.writeFile(prefix, suffix, content);

        // Then
        // Verify the temporary file is created with expected content
        File tempFile = new File(System.getProperty("java.io.tmpdir"), prefix + "*" + suffix);
        assertTrue(verifyFileContent(tempFile.getPath(), content));
    }

    @Test
    void testWriteFileWithLogSuffix() throws IOException {
        // Given
        String prefix = "log_";
        String suffix = ".log";
        String content = "2023-10-01 Logging data";

        // When
        fileHandler.writeFile(prefix, suffix, content);

        // Then
        // Verify the temporary file is created with expected content
        File tempFile = new File(System.getProperty("java.io.tmpdir"), prefix + "*" + suffix);
        assertTrue(verifyFileContent(tempFile.getPath(), content));
    }

    @Test
    void testWriteFileWithoutSuffix() throws IOException {
        // Given
        String prefix = "data";
        String suffix = "";
        String content = "Temporary data content.";

        // When
        fileHandler.writeFile(prefix, suffix, content);

        // Then
        // Verify the temporary file is created with expected content
        File tempFile = new File(System.getProperty("java.io.tmpdir"), prefix + "*");
        assertTrue(verifyFileContent(tempFile.getPath(), content));
    }

    // Helper method to verify file content
    private boolean verifyFileContent(String filePath, String expectedContent) throws IOException {
        return Files.readAllLines(Paths.get(filePath)).stream().anyMatch(line -> line.contains(expectedContent));
    }
}

