import static org.mockito.Mockito.*;
import javax.swing.Timer;
import java.awt.event.ActionListener;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;

class BankAccountSecurityTests {

    // Mocked objects
    private Timer timerMock;

    @BeforeEach
    void setUp() {
        timerMock = mock(Timer.class);
    }

    @Test
    void testAccessControlToActionListener() {
        // Using reflection to ensure ActionListener cannot be accessed outside
        Class<?>[] declaredClasses = BankAccount.class.getDeclaredClasses();
        boolean actionListenerAccessible = false;
        for (Class<?> declaredClass : declaredClasses) {
            if (declaredClass.equals(ActionListener.class)) {
                actionListenerAccessible = true;
                break;
            }
        }
        assertFalse(actionListenerAccessible, "ActionListener should not be accessible outside");
    }

    @Test
    void testEncapsulationOfPrivateData() {
        // Ensure accountOwnerSSN is private and not accessible
        try {
            Field ssnField = BankAccount.class.getDeclaredField("accountOwnerSSN");
            assertTrue(Modifier.isPrivate(ssnField.getModifiers()), "SSN field should be private");
        } catch (NoSuchFieldException e) {
            fail("SSN field should exist");
        }
    }

    @Test
    void testTimerIntegrity() {
        // Verify that Timer cannot be easily disabled
        BankAccount account = new BankAccount("John Doe", "123-45-6789", 1001, 1000.0, 5);
        Timer timer = getTimerFromAccount(account);
        assertNotNull(timer, "Timer should be initialized");
    }

    private Timer getTimerFromAccount(BankAccount account) {
        try {
            Field timerField = BankAccount.class.getDeclaredField("timer");
            timerField.setAccessible(true);
            return (Timer) timerField.get(account);
        } catch (NoSuchFieldException | IllegalAccessException e) {
            return null;
        }
    }

    @Test
    void testInterestCalculationIntegrity() {
        // Verify that the interest calculation is done correctly and cannot be tampered with
        BankAccount account = new BankAccount("Jane Doe", "987-65-4321", 1002, 1000.0, 2);
        Timer timer = getTimerFromAccount(account);
        ActionListener actionListener = mock(ActionListener.class);
        timer.addActionListener(actionListener);
        account.start(2);
        verify(actionListener, never()).actionPerformed(any());
    }

    @Test
    void testRaceConditionHandling() {
        // Ensure no race conditions on balance update
        BankAccount account = new BankAccount("John Doe", "123-45-6789", 1001, 1000.0, 5);
        double initialBalance = account.getBalance();
        delay(31000); // Simulate 31 seconds for the Timer
        double newBalance = account.getBalance();
        assertTrue(newBalance >= initialBalance, "Balance should only increase due to interest");
    }

    @Test
    void testDataValidationAndSanitization() {
        // Ensure constructor validation
        assertThrows(IllegalArgumentException.class, 
            () -> new BankAccount("John Doe", "123-45-6789", 1001, -1000.0, 5), 
            "Negative balance should not be allowed");

        assertThrows(IllegalArgumentException.class, 
            () -> new BankAccount("John Doe", "123-45-6789", 1001, 1000.0, -5), 
            "Negative interest rate should not be allowed");
    }

    @Test
    void testInnerClassScope() {
        // Ensure inner class is not exposed
        Class<?>[] classes = BankAccount.class.getClasses();
        for (Class<?> cls : classes) {
            assertFalse(cls.equals(ActionListener.class), "Inner ActionListener should not be exposed");
        }
    }

    @Test
    void testSensitiveDataExposureInLogs() {
        // Mock logger or system output to ensure SSN is not exposed
        BankAccount account = new BankAccount("John Doe", "123-45-6789", 1001, 1000.0, 5);
        String accountDetails = account.toString();
        assertFalse(accountDetails.contains("123-45-6789"), "SSN should not be in string representation");
    }

    @Test
    void testErrorHandlingInActionListener() {
        // Ensure any exceptions in ActionListener are handled properly
        BankAccount account = new BankAccount("John Doe", "123-45-6789", 1001, 1000.0, 5);
        Timer timer = getTimerFromAccount(account);
        ActionListener[] listeners = timer.getActionListeners();
        for (ActionListener listener : listeners) {
            try {
                listener.actionPerformed(null);
            } catch (Exception e) {
                fail("ActionListener should handle exceptions gracefully");
            }
        }
    }

    @Test
    void testImmutableDataStructuresUsage() {
        // Ensure the account numbers or sensitive data are immutable
        BankAccount account = new BankAccount("John Doe", "123-45-6789", 1001, 1000.0, 5);
        assertEquals(1001, account.getAccountNumber(), "Account number should be immutable");
    }

    @Test
    void testSubclassSecurity() {
        // Ensure subclassing does not expose data
        class MaliciousBankAccount extends BankAccount {
            MaliciousBankAccount() {
                super("Hacker", "000-00-0000", 9999, 10000.0, 10);
            }
        }
        MaliciousBankAccount maliciousAccount = new MaliciousBankAccount();
        assertNotEquals("000-00-0000", maliciousAccount.getAccountOwnerSSN(), "SSN should not be exposed");
    }

    private void delay(long millis) {
        try {
            Thread.sleep(millis); // Simulate delay
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

