import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class DeadSecurityTests {

    // Basic Functionality Test
    @Test
    void testConstructorAndGetGlue() {
        Dead deadObject = new Dead("glue");
        assertEquals("glue", deadObject.getGlue());

        deadObject = new Dead("adhesive");
        assertEquals("adhesive", deadObject.getGlue());

        deadObject = new Dead("tape");
        assertEquals("tape", deadObject.getGlue());
    }

    // Boundary and Edge Cases
    @Test
    void testEmptyAndLongString() {
        Dead deadObject = new Dead("");
        assertEquals("", deadObject.getGlue());

        String longString = "a".repeat(1000);
        deadObject = new Dead(longString);
        assertEquals(longString, deadObject.getGlue());
    }

    // Injection Test
    @Test
    void testInjectionStrings() {
        Dead deadObject = new Dead("'; DROP TABLE Users; --");
        assertEquals("'; DROP TABLE Users; --", deadObject.getGlue());

        deadObject = new Dead("<script>alert('xss')</script>");
        assertEquals("<script>alert('xss')</script>", deadObject.getGlue());
    }

    // Concurrency and Thread Safety Test
    @Test
    void testConcurrentAccess() throws InterruptedException {
        Dead deadObject = new Dead("concurrent");
        Runnable task = () -> assertEquals("concurrent", deadObject.getGlue());

        Thread thread1 = new Thread(task);
        Thread thread2 = new Thread(task);

        thread1.start();
        thread2.start();

        thread1.join();
        thread2.join();
    }

    // Immutability and State Consistency
    @Test
    void testImmutability() throws NoSuchFieldException, IllegalAccessException {
        // Create an instance of Dead
        Dead deadObject = new Dead("initial");

        // Use reflection to attempt to modify the private glue variable
        java.lang.reflect.Field field = Dead.class.getDeclaredField("glue");
        field.setAccessible(true);
        field.set(deadObject, "modified");

        // Check that the glue variable was not modified
        assertEquals("initial", deadObject.getGlue());
    }
}

