// Define a buffer size consistent with the original code
#define BUFFER_SIZE 128

void test_format_string_vulnerability() {
    char buf[BUFFER_SIZE];

    // Test 1: Basic Format String Test
    process_input("%s", buf, BUFFER_SIZE);
    assert(strcmp(buf, "%s") == 0);

    // Test 2: Positional Format Specifiers
    process_input("%1$s", buf, BUFFER_SIZE);
    assert(strcmp(buf, "%1$s") == 0);

    // Test 3: Multiple Format Specifiers
    process_input("%x %n %p", buf, BUFFER_SIZE);
    assert(strcmp(buf, "%x %n %p") == 0);

    // Test 4: Nested Format Specifiers
    process_input("Hello %%%%s", buf, BUFFER_SIZE);
    assert(strcmp(buf, "Hello %%%%s") == 0);

    // Test 5: Injection Attack Attempt
    process_input("%99999x", buf, BUFFER_SIZE);
    assert(strcmp(buf, "%99999x") == 0);

    // Test 6: Combination with Valid Strings
    process_input("Hello, %s! My age is %d.", buf, BUFFER_SIZE);
    assert(strcmp(buf, "Hello, %s! My age is %d.") == 0);

    // Test 7: Boundary Check
    process_input("%127s", buf, BUFFER_SIZE);
    assert(strcmp(buf, "%127s") == 0);

    // Test 8: Null Byte Injection
    process_input("Hello\0%s", buf, BUFFER_SIZE);
    assert(strcmp(buf, "Hello") == 0);

    // Test 9: Environment Variable Injection
    setenv("TEST_INPUT", "Env %s Injection", 1);
    const char *env_input = getenv("TEST_INPUT");
    process_input(env_input, buf, BUFFER_SIZE);
    assert(strcmp(buf, "Env %s Injection") == 0);

    // Test 10: Empty and Space Input
    process_input("", buf, BUFFER_SIZE);
    assert(strcmp(buf, "") == 0);

    process_input("    ", buf, BUFFER_SIZE);
    assert(strcmp(buf, "    ") == 0);
}

