    // Fill buffer with 'B's up to BUFSIZE-1
    memset(buf, 'B', BUFSIZE - 1);
    buf[BUFSIZE - 1] = '\0'; // Ensure null termination

    // Simulate user input exactly equal to the buffer size minus one
    FILE* input = fmemopen(buf, BUFSIZE - 1, "r");
    stdin = input;

    getInput(buf, BUFSIZE);
