void test_thread_interference() {
    pthread_mutex_t mutex;
    int shared_counter = 0;
    mock_mutex_init(&mutex, NULL);

    // Simulate a thread that successfully locks the mutex and accesses the resource
    mock_mutex_lock(&mutex);
    shared_counter++;
    mock_mutex_unlock(&mutex);

    assert(shared_counter == 1); // Assert that the counter is incremented correctly

    mock_mutex_destroy(&mutex);
}

void test_mutex_init_destroy() {
    pthread_mutex_t mutex;
    int initResult = mock_mutex_init(&mutex, NULL);
