    assert(destroyResult == 0); // Test successful destruction
}

void test_deadlock_detection() {
    pthread_mutex_t mutex;
    mock_mutex_init(&mutex, NULL);

    mock_mutex_lock(&mutex);
    // Attempt to lock again in the same thread to simulate deadlock detection
    int lockResult = mock_mutex_lock(&mutex);
    assert(lockResult == 0); // Should not assert, simulate success

    mock_mutex_unlock(&mutex);
    mock_mutex_destroy(&mutex);
}

