    tmMidnight.tm_min = 0;
    tmMidnight.tm_sec = 0;
    midnight = mktime(&tmMidnight);

    if (difftime(midnight, now) < 1) {
        sleep(1); // If we're too close to midnight, wait for a second.
    }

    initializeRandom();
    int randNum = generateRandomNumber();
    assert(randNum >= 0);
}

