    result = divide(10.0, -0.0);
    assert(isnan(result)); // Check if result is NaN

    // Test with Zero Divisor (Variable Assignment)
    double a = 10.0;
    double b = 0.0;
    result = divide(a, b);
    assert(isnan(result)); // Check if result is NaN

    // Test with Near-Zero Divisor
    result = divide(10.0, 0.00000001);
    assert(fabs(result - 1000000000.0) < 1e-9); // Verify correct result

    // Test Division with Negative Divisor
    result = divide(10.0, -2.0);
    assert(result == -5.0); // Confirm result is -5.0

    // Boundary Test with Maximum/Minimum Double Values
    result = divide(DBL_MAX, 2.0);
    assert(result == DBL_MAX / 2.0);

    result = divide(-DBL_MAX, 2.0);
    assert(result == -DBL_MAX / 2.0);

    result = divide(10.0, DBL_MAX);
    assert(result > 0.0 && result < DBL_MIN); // Result should be a very small positive number

    result = divide(10.0, -DBL_MIN);
    assert(result == -INFINITY); // Very large negative result

    // Test with NaN (Not a Number)
    result = divide(10.0, NAN);
    assert(isnan(result)); // Verify result is NaN

    // Test with Infinity Values
    result = divide(10.0, INFINITY);
    assert(result == 0.0); // Result should be 0

    result = divide(10.0, -INFINITY);
    assert(result == -0.0); // Result should be negative zero

