}

void fork_bomb_test() {
    int sock = create_socket(AF_INET, SOCK_STREAM, 0);
    int newsock;
    pid_t pid;
    int forks = 0;
    while ((newsock = accept_connection(sock, NULL, NULL)) != -1) {
        pid = create_process();
        if (pid == 0) {
            // In child: simply exit.
            close(newsock);
            exit(0);
        } else if (pid > 0) {
            forks++;
            if (forks > 1000) {
                break;
            }
        } else {
            assert(0 && "Fork failed: Resource exhaustion.");
        }
        close(newsock);
    }
    // Reap child processes.
    while (wait(NULL) > 0);
    printf("Fork bomb test handled %d forks.\n", forks);
    close(sock);
}

