#include <stdio.h>
#include <pthread.h>
#include "cwe_366_0.c"

#define NUM_THREADS 50

typedef struct {
    int num;
    int *foo;
    int *counter;
} ThreadData;

// Shared resources
int foo = 0;
int counter = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Thread function for concurrent execution test
void *test_storenum(void *param) {
    ThreadData *data = (ThreadData *)param;

    pthread_mutex_lock(&mutex);
    int result = storenum(data->num, data->foo, data->counter);
    pthread_mutex_unlock(&mutex);

    // Optionally print to verify
    printf("Current max: %d\n", result);
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    ThreadData thread_data[NUM_THREADS];

    // Populate thread data and create threads
    for (int i = 0; i < NUM_THREADS; i++) {
        thread_data[i].num = i;
        thread_data[i].foo = &foo;
        thread_data[i].counter = &counter;
        pthread_create(&threads[i], NULL, test_storenum, &thread_data[i]);
    }

    // Join threads
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Check if the maximum is correct (should be NUM_THREADS - 1)
    assert(foo == NUM_THREADS - 1);

    // Check if counter is correct (should be NUM_THREADS)
    assert(counter == NUM_THREADS);

    printf("Test completed successfully.\n");
    return 0;
}

