// Test function to validate copy_string behavior
void test_copy_string() {
    // Define source string and destination buffer
    const char *source = "Hello, World!";
    char dest[10];

    // Invocation example where source is longer
    copy_string(dest, source, sizeof(dest));
    assert(dest[9] == '\0'); // Ensure the last byte is a null-terminator
    assert(strncmp(dest, "Hello, Wo", 9) == 0); // Check if truncated correctly

    // Test with exact size match and null-termination
    char exact_dest[14];
    copy_string(exact_dest, source, sizeof(exact_dest));
    assert(exact_dest[13] == '\0'); // Ensure null-termination
    assert(strcmp(exact_dest, source) == 0); // Full copy should match

    // Test with larger buffer
    char large_dest[20];
    copy_string(large_dest, source, sizeof(large_dest));
    assert(large_dest[13] == '\0'); // Ensure null-termination
    assert(strcmp(large_dest, source) == 0); // Full source copied

    // Empty source test
    char empty_dest[5];
    source = "";
    copy_string(empty_dest, source, sizeof(empty_dest));
    assert(empty_dest[0] == '\0'); // Empty destination should be null-terminated

    // Destination size too small, ensure safe truncation and null-termination
    char small_dest[2];
    source = "ABCD";
    copy_string(small_dest, source, sizeof(small_dest));
    assert(small_dest[1] == '\0'); // Ensure null-termination
    assert(small_dest[0] == 'A'); // Only first character should copy
}

