// Helper function to capture and compare output of a function
int capture_output(const char *expected_child, const char *expected_parent) {
    int pipefd[2];
    pid_t pid;
    char buffer[256];

    // Create a pipe
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    }

    pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }

    if (pid == 0) {
        // Child process: redirect stdout to pipe
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);

        process_logic(expected_child, expected_parent);

        exit(0);
    } else {
        // Parent process: read from pipe
        close(pipefd[1]);
        read(pipefd[0], buffer, sizeof(buffer));
        close(pipefd[0]);

        // Check if output contains expected strings
        if (strstr(buffer, expected_child) && strstr(buffer, expected_parent)) {
            return 0;
        } else {
            return 1;
        }
    }
}

