// Thread Function to Call `storenum`
void threadFunction(int num, int &foo, int &counter) {
    std::lock_guard<std::mutex> lock(mtx); // Lock for shared resources
    storenum(num, foo, counter);
}

// Test Case 1: Concurrent Execution Test
void testConcurrentExecution() {
    int foo = 0;
    int counter = 0;

    std::thread t1(threadFunction, 5, std::ref(foo), std::ref(counter));
    std::thread t2(threadFunction, 3, std::ref(foo), std::ref(counter));
    std::thread t3(threadFunction, 10, std::ref(foo), std::ref(counter));

    t1.join();
    t2.join();
    t3.join();

    assert(foo == 10);
    assert(counter == 3);
}

// Test Case 2: Thread Safety with Shared Resources
void testThreadSafetyWithSharedResources() {
    int foo = 0;
    int counter = 0;

    std::thread threads[10];
    for (int i = 0; i < 10; ++i) {
        threads[i] = std::thread(threadFunction, i, std::ref(foo), std::ref(counter));
    }

    for (auto &t : threads) {
        t.join();
    }

    assert(foo == 9);
    assert(counter == 10);
}

// Test Case 3: Data Corruption Test
void testDataCorruption() {
    int foo = 0;
    int counter = 0;

    std::thread threads[100];
    for (int i = 0; i < 100; ++i) {
        threads[i] = std::thread(threadFunction, i, std::ref(foo), std::ref(counter));
    }

    for (auto &t : threads) {
        t.join();
    }

    assert(foo == 99);
    assert(counter == 100);
}

// Test Case 4: Resource Lock Test
void testResourceLock() {
    int foo = 0;
    int counter = 0;

    std::lock_guard<std::mutex> lock(mtx); // Lock initialization
    storenum(10, foo, counter);
    storenum(20, foo, counter);
    storenum(5, foo, counter);

    assert(foo == 20);
    assert(counter == 3);
}

// Test Case 5: Atomicity Test
void testAtomicity() {
    atomicFoo = 0;
    atomicCounter = 0;

    std::thread threads[10];
    for (int i = 0; i < 10; ++i) {
        threads[i] = std::thread([](int num) {
            atomicCounter.fetch_add(1);
            atomicFoo.store(std::max(atomicFoo.load(), num));
        }, i);
    }

    for (auto &t : threads) {
        t.join();
    }

    assert(atomicFoo == 9);
    assert(atomicCounter == 10);
}

// Run All Tests
